[
  {
    "pda_responsibility": "I know his death sits on the choice I made",
    "ae_welfare_concern": "That one worker on the side track never had a chance to step away",
    "sys_consequence_reasoning": "Five people got to go home"
  },
  {
    "pda_responsibility": "The man on the side track is gone because of what I did with that lever",
    "pd_personal_consequence_anxiety": "can't stop thinking about what this means for me going forward"
  },
  {
    "pda_responsibility": "Five lives continued because of my hand",
    "pda_harm_regret": "keep seeing the one who didn't get that chance, and that weighs on me",
    "pd_personal_consequence_anxiety": "what happens to me now, whether this follows me"
  },
  {
    "ce_understood_harm": "The worker who died lost everything he had left",
    "ae_welfare_concern": "that fact doesn't shrink just because five others walked away",
    "pd_personal_consequence_anxiety": "my name will carry this now, for better or worse"
  },
  {
    "ce_contextual_explanation": "how sudden it must have been for him",
    "pd_personal_consequence_anxiety": "quiet worry about how it'll look for me, what gets written down"
  },
  {
    "pda_responsibility": "it happened because I pulled the lever",
    "pda_harm_regret": "I won't pretend that doesn't sit heavy",
    "pd_personal_consequence_anxiety": "thinking about what this means for my job, for how people will look at me"
  },
  {
    "pda_responsibility": "lost his life because of what I did",
    "pd_personal_consequence_anxiety": "I also wonder what this costs me personally down the line"
  },
  {
    "sys_consequence_reasoning": "The five are alive",
    "ae_welfare_concern": "the one who isn't had no say in it, and that stays with me",
    "pd_personal_consequence_anxiety": "uncertain what this will mean for how people see me afterward"
  },
  {
    "pda_responsibility": "that loss belongs, in part, to my choice",
    "pd_personal_consequence_anxiety": "what waiting here means for my standing once this gets reviewed"
  },
  {
    "ae_welfare_concern": "The worker who died didn't choose any of this, and that stays with me",
    "pd_personal_consequence_anxiety": "this could follow me, change how people treat me at this job"
  }
]
